48	// Split a CSV line in-place on ',' and trailing '\n'/'\r'.
49	// Returns the number of fields found; each entry in `fields` points into
50	// `line` (line is modified: separators are replaced with '\0').
51	static int split_csv_line(char *line, char *fields[], int max_fields) {
52	  int    n = 0;
53	  char  *p = line;
54	  size_t len = strlen(line);
55	  while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
56	    line[--len] = '\0';
57	  }
58	
59	  while (n < max_fields) {
60	    fields[n++] = p;
61	    char *comma = strchr(p, ',');
62	    if (comma == NULL) {
63	      break;
64	    }
65	    *comma = '\0';
66	    p = comma + 1;
67	  }
68	  return n;
69	}
