71	static int load_acc_data(const char *filepath,
72	                         AccSample  *samples,
73	                         int         max_samples) {
74	  FILE *fp = fopen(filepath, "r");
75	  if (!fp) {
76	    LOGE(TAG, "Failed to open acc file: %s", filepath);
77	    return -1;
78	  }
79	
80	  char line[MAX_LINE_LEN];
81	  // Skip line 1 (Info) and line 2 (header)
82	  fgets(line, MAX_LINE_LEN, fp);
83	  fgets(line, MAX_LINE_LEN, fp);
84	
85	  int count = 0;
86	  while (fgets(line, MAX_LINE_LEN, fp) && count < max_samples) {
87	    AccSample *s = &samples[count];
88	    if (sscanf(line,
89	               "%lu,%lu,%f,%f,%f",
90	               &s->current_ts_ms,
91	               &s->event_ts_ms,
92	               &s->acc_x,
93	               &s->acc_y,
94	               &s->acc_z) == 5) {
95	      count++;
96	    }
97	  }
98	
99	  fclose(fp);
100	  LOGI(TAG, "Loaded %d acc samples from %s", count, filepath);
101	  return count;
102	}
