104	// Load baro-<N>hz.csv, tolerating two historical header layouts:
105	//  - New layout: single header line
106	//    "FrameID,CurrentTimestamp(ms),EventTimestamp(ms),baro,temperature"
107	//    (5 fields per data row)
108	//  - Old layout: 3 header lines (Info line, real header line, a
109	//    "p0:...:..." line), data rows have 4 fields:
110	//    "CurrentTimestamp(ms),EventTimestamp(ms),baro,temperature"
111	// The two layouts are told apart by checking whether the first line
112	// contains "baro" (new layout's single header does).
113	static int load_baro_data(const char *filepath,
114	                          BaroSample *samples,
115	                          int         max_samples) {
116	  FILE *fp = fopen(filepath, "r");
117	  if (!fp) {
118	    LOGE(TAG, "Failed to open baro file: %s", filepath);
119	    return -1;
120	  }
121	
122	  char line[MAX_LINE_LEN];
123	  if (fgets(line, MAX_LINE_LEN, fp) == NULL) {
124	    fclose(fp);
125	    return -1;
126	  }
127	  int new_layout = (strstr(line, "baro") != NULL);
128	  if (!new_layout) {
129	    // Old layout: current line was the Info line; skip the real header
130	    // line and the p0 line as well.
131	    fgets(line, MAX_LINE_LEN, fp);
132	    fgets(line, MAX_LINE_LEN, fp);
133	  }
134	
135	  int count = 0;
136	  while (fgets(line, MAX_LINE_LEN, fp) && count < max_samples) {
137	    char *fields[MAX_FIELDS];
138	    int   n = split_csv_line(line, fields, MAX_FIELDS);
139	    // New layout has an extra leading FrameID field.
140	    int base = new_layout ? 1 : 0;
141	    if (n < base + 4) {
142	      continue;
143	    }
144	    BaroSample *s = &samples[count];
145	    s->current_ts_ms = strtoul(fields[base], NULL, 10);
146	    s->event_ts_ms = strtoul(fields[base + 1], NULL, 10);
147	    s->baro = strtof(fields[base + 2], NULL);
148	    s->temperature = strtof(fields[base + 3], NULL);
149	    count++;
150	  }
151	
152	  fclose(fp);
153	  LOGI(TAG, "Loaded %d baro samples from %s", count, filepath);
154	  return count;
155	}
