157	// Load acc (AlignedData rows) and baro rows mixed in algo_har.csv, keeping
158	// each sample in the exact order it appears in the file (no re-sorting, no
159	// timestamp interpolation), so the recognizer is fed the same sequence the
160	// device produced.
161	//
162	// algo_har.csv columns:
163	//   FrameID,DataName,CurrentTimestamp(ms),EventTimestamp(ms),acc_x,acc_y,
164	//   acc_z,activity_type
165	// "AlignedData" rows use all 8 fields; "baro" rows only carry
166	// FrameID,DataName,CurrentTimestamp(ms),EventTimestamp(ms),<baro>,<altitude>
167	// (6 fields), with the pressure value stored in the position of the first
168	// data column (acc_x).
169	static int load_algo_har_data(const char *filepath,
170	                              AccSample  *acc_samples,
171	                              int         max_acc_samples,
172	                              BaroSample *baro_samples,
173	                              int         max_baro_samples,
174	                              int        *baro_count_out) {
175	  FILE *fp = fopen(filepath, "r");
176	  if (!fp) {
177	    LOGE(TAG, "Failed to open algo_har file: %s", filepath);
178	    return -1;
179	  }
180	
181	  char line[MAX_LINE_LEN];
182	  // Skip the header line.
183	  fgets(line, MAX_LINE_LEN, fp);
184	
185	  int acc_count = 0;
186	  int baro_count = 0;
187	  while (fgets(line, MAX_LINE_LEN, fp) && acc_count < max_acc_samples &&
188	         baro_count < max_baro_samples) {
189	    char *fields[MAX_FIELDS];
190	    int   n = split_csv_line(line, fields, MAX_FIELDS);
191	    if (n < 4) {
192	      continue;
193	    }
194	
195	    const char *data_name = fields[1];
196	    uint64_t    current_ts_ms = strtoul(fields[2], NULL, 10);
197	    uint64_t    event_ts_ms = strtoul(fields[3], NULL, 10);
198	
199	    if (strcmp(data_name, "baro") == 0) {
200	      if (n < 5) {
201	        continue;
202	      }
203	      BaroSample *s = &baro_samples[baro_count];
204	      s->current_ts_ms = current_ts_ms;
205	      s->event_ts_ms = event_ts_ms;
206	      s->baro = strtof(fields[4], NULL);
207	      s->temperature = 0.0f;  // Not present in algo_har.csv
208	      baro_count++;
209	    } else {
210	      // Treat everything else (e.g. "AlignedData") as an acc sample.
211	      if (n < 7) {
212	        continue;
213	      }
214	      AccSample *s = &acc_samples[acc_count];
215	      s->current_ts_ms = current_ts_ms;
216	      s->event_ts_ms = event_ts_ms;
217	      s->acc_x = strtof(fields[4], NULL);
218	      s->acc_y = strtof(fields[5], NULL);
219	      s->acc_z = strtof(fields[6], NULL);
220	      acc_count++;
221	    }
222	  }
223	
224	  fclose(fp);
225	  LOGI(TAG,
226	       "Loaded %d acc samples and %d baro samples from %s (original order)",
227	       acc_count,
228	       baro_count,
229	       filepath);
230	  *baro_count_out = baro_count;
231	  return acc_count;
232	}
