234	static int file_exists(const char *filepath) {
235	  struct stat st;
236	  return stat(filepath, &st) == 0;
237	}
238	
239	// Find a file matching "baro-*hz.csv" in data_dir (e.g. baro-1hz.csv,
240	// baro-8hz.csv, baro-16hz.csv, baro-25hz.csv -- the sample rate suffix
241	// varies across recording batches/devices). Writes the full path into
242	// `out_path` (size MAX_PATH_LEN) and returns 1 on success, 0 if not found.
243	static int find_baro_hz_file(const char *data_dir, char *out_path) {
244	  DIR *dir = opendir(data_dir);
245	  if (!dir) {
246	    return 0;
247	  }
248	  int            found = 0;
249	  struct dirent *entry;
250	  while ((entry = readdir(dir)) != NULL) {
251	    const char *name = entry->d_name;
252	    size_t      len = strlen(name);
253	    // Match prefix "baro-" and suffix "hz.csv".
254	    if (len > 10 && strncmp(name, "baro-", 5) == 0 &&
255	        strcmp(name + len - 6, "hz.csv") == 0) {
256	      snprintf(out_path, MAX_PATH_LEN, "%s/%s", data_dir, name);
257	      found = 1;
258	      break;
259	    }
260	  }
261	  closedir(dir);
262	  return found;
263	}
