265	int main(int argc, char *argv[]) {
266	  if (argc < 2) {
267	    fprintf(stderr, "Usage: %s <data_folder_path>\n", argv[0]);
268	    fprintf(stderr,
269	            "  data_folder should contain either algo_har.csv, or the pair "
270	            "accel-25hz.csv + baro-<N>hz.csv\n");
271	    return 1;
272	  }
273	
274	  const char *data_dir = argv[1];
275	  char        algo_har_path[MAX_PATH_LEN];
276	  char        acc_path[MAX_PATH_LEN];
277	  char        baro_path[MAX_PATH_LEN] = {0};
278	  snprintf(algo_har_path, MAX_PATH_LEN, "%s/algo_har.csv", data_dir);
279	  snprintf(acc_path, MAX_PATH_LEN, "%s/accel-25hz.csv", data_dir);
280	  int has_baro_file = find_baro_hz_file(data_dir, baro_path);
281	
282	  LOGI(TAG, "Activity recognizer demo - file mode");
283	  LOGI(TAG, "Data folder: %s", data_dir);
284	
285	  // Load data
286	  AccSample *acc_samples =
287	      (AccSample *)malloc(MAX_ACC_SAMPLES * sizeof(AccSample));
288	  BaroSample *baro_samples =
289	      (BaroSample *)malloc(MAX_BARO_SAMPLES * sizeof(BaroSample));
290	  if (!acc_samples || !baro_samples) {
291	    LOGE(TAG, "Failed to allocate memory");
292	    free(acc_samples);
293	    free(baro_samples);
294	    return 1;
295	  }
296	
297	  int acc_count;
298	  int baro_count;
299	  if (file_exists(algo_har_path)) {
300	    LOGI(TAG, "Found algo_har.csv, loading acc/baro from it (original order)");
301	    acc_count = load_algo_har_data(algo_har_path,
302	                                   acc_samples,
303	                                   MAX_ACC_SAMPLES,
304	                                   baro_samples,
305	                                   MAX_BARO_SAMPLES,
306	                                   &baro_count);
307	    // algo_har.csv 可能不含混入的 baro 行（如部分设备把气压单独存成
308	    // baro-<N>hz.csv），此时回退去找独立的 baro 文件，避免爬楼判定因缺 baro
309	    // 而失效。
310	    if (baro_count <= 0 && has_baro_file) {
311	      LOGI(TAG, "algo_har.csv has no baro rows, falling back to %s", baro_path);
312	      baro_count = load_baro_data(baro_path, baro_samples, MAX_BARO_SAMPLES);
313	    }
314	  } else {
315	    LOGI(TAG,
316	         "algo_har.csv not found, falling back to accel-25hz.csv / "
317	         "baro-<N>hz.csv");
318	    acc_count = load_acc_data(acc_path, acc_samples, MAX_ACC_SAMPLES);
319	    baro_count = 0;
320	    if (acc_count > 0 && has_baro_file) {
321	      baro_count = load_baro_data(baro_path, baro_samples, MAX_BARO_SAMPLES);
322	    } else if (acc_count > 0) {
323	      LOGW(TAG, "No baro-*hz.csv file found in %s", data_dir);
324	    }
325	  }
326	
327	  if (acc_count <= 0) {
328	    LOGE(TAG, "No acc data loaded");
329	    free(acc_samples);
330	    free(baro_samples);
331	    return 1;
332	  }
333	
334	  // mi_activity_recognizer_process_baro 内部假设每次调用对应 1 秒
335	  // (HAR_BARO_FS == 1，参见 har_model.h 的 BARO_WINDOW_LEN 定义)，如果原始
336	  // baro 文件采样率高于 1Hz（如 8/16/25Hz），必须先降采样到 1Hz 再喂，否则
337	  // 窗口时间跨度语义会被压缩，导致爬楼判定的气压差分永远达不到阈值。
338	  if (baro_count > 1) {
339	    int      resampled_count = 0;
340	    uint32_t last_sec = 0;
341	    int      have_last_sec = 0;
342	    for (int i = 0; i < baro_count; i++) {
343	      uint32_t sec = baro_samples[i].event_ts_ms / 1000;
344	      if (!have_last_sec || sec != last_sec) {
345	        baro_samples[resampled_count] = baro_samples[i];
346	        resampled_count++;
347	        last_sec = sec;
348	        have_last_sec = 1;
349	      }
350	    }
351	    if (resampled_count != baro_count) {
352	      LOGI(TAG,
353	           "Resampled baro from %d samples to %d (~1Hz) before feeding to "
354	           "the recognizer",
355	           baro_count,
356	           resampled_count);
357	    }
358	    baro_count = resampled_count;
359	  }
360	
361	  if (baro_count <= 0) {
362	    LOGW(TAG, "No baro data loaded, will run without baro");
363	  }
364	
365	  LOGI(TAG,
366	       "Data loaded: %d acc samples (%.1f s), %d baro samples (%.1f s)",
367	       acc_count,
368	       acc_count / 25.0,
369	       baro_count,
370	       (double)baro_count);
371	
372	  // Init recognizer
373	  void *recognizer = mi_activity_recognizer_new();
374	  mi_activity_recognizer_init(recognizer, 0.85, 16);
375	
376	  LOGI(TAG, "Algorithm version: %u", mi_activity_recognizer_get_version());
377	
378	  clock_t begin = clock();
379	  int     baro_idx = 0;
380	  int8_t  last_activity = -1;
381	
382	  for (int i = 0; i < acc_count; i++) {
383	    AccSample *a = &acc_samples[i];
384	    int8_t     ret = mi_activity_recognizer_process(
385	        recognizer, a->acc_x, a->acc_y, a->acc_z);
386	
387	    if (ret) {
388	      int8_t type = mi_activity_recognizer_get_activity(recognizer);
389	      if (type != last_activity) {
390	        LOGI(TAG,
391	             "Activity CHANGED: %s -> %s (acc sample #%d, EventTS=%lu ms)",
392	             last_activity >= 0 ? HAR_TYPE_NAMES[last_activity] : "None",
393	             HAR_TYPE_NAMES[type],
394	             i,
395	             a->event_ts_ms);
396	        last_activity = type;
397	      }
398	    }
399	
400	    // Feed baro: every 25 acc samples (1Hz), match by checking if we have
401	    // a baro sample whose EventTimestamp is <= current acc EventTimestamp
402	    if (baro_idx < baro_count &&
403	        baro_samples[baro_idx].event_ts_ms <= a->event_ts_ms) {
404	      mi_activity_recognizer_process_baro(
405	          recognizer,
406	          (uint32_t)baro_samples[baro_idx].event_ts_ms,
407	          baro_samples[baro_idx].baro);
408	      baro_idx++;
409	    }
410	  }
411	
412	  clock_t end = clock();
413	  double  time_spent = (double)(end - begin) / CLOCKS_PER_SEC * 1000;
414	
415	  LOGI(TAG, "Processing done. Time spent: %.3f ms", time_spent);
416	  LOGI(TAG, "Baro samples consumed: %d / %d", baro_idx, baro_count);
417	  LOGI(TAG,
418	       "Final activity: %s",
419	       last_activity >= 0 ? HAR_TYPE_NAMES[last_activity] : "None");
420	
421	  mi_activity_recognizer_free(recognizer);
422	  free(acc_samples);
423	  free(baro_samples);
424	
425	  return 0;
426	}
