14	class MIActivityRecognizerPy {
15	 public:
16	  MIActivityRecognizerPy(const float thd, const int vote_len) {
17	    recognizer_ = mi_activity_recognizer_new();
18	    mi_activity_recognizer_init(recognizer_, thd, vote_len);
19	  }
20	
21	  void initAlgo(const float thd, const int vote_len) {
22	    mi_activity_recognizer_init(recognizer_, thd, vote_len);
23	  }
24	
25	  int handleData(float acc_x, float acc_y, float acc_z) {
26	    return mi_activity_recognizer_process(recognizer_, acc_x, acc_y, acc_z);
27	  }
28	
29	  void handleBaro(uint32_t ts_ms, float baro) {
30	    mi_activity_recognizer_process_baro(recognizer_, ts_ms, baro);
31	  }
32	
33	  // Barometer state readers for the offline evaluation scripts. They reach
34	  // into the instance through mi_activity_recognizer_internal.h on purpose,
35	  // so that the delivered interface (mi_activity_recognizer.h) does not have
36	  // to carry debug-only accessors.
37	  int getInWater() {
38	    MIActivityRecognizer *rec = (MIActivityRecognizer *)recognizer_;
39	    return mi_har_model_get_in_water(&rec->mdl);
40	  }
41	
42	  int getStairClimbing() {
43	    MIActivityRecognizer *rec = (MIActivityRecognizer *)recognizer_;
44	    return mi_har_model_get_stair_climbing(&rec->mdl);
45	  }
46	
47	  std::vector<float> getPrediction() {
48	    // 模型原生输出 MI_HARM_NUM_TYPES（8类，含 Swim，参见 mi_activity_type.h）
49	    // 的概率值；此前硬编码只取 7 个，漏掉了最后一类 Swim 的概率。
50	    float             *res = mi_activity_recognizer_get_predicts(recognizer_);
51	    std::vector<float> v{res, res + MI_HARM_NUM_TYPES};
52	    return v;
53	  }
54	
55	  int getActivity() {
56	    return mi_activity_recognizer_get_activity(recognizer_);
57	  }
58	
59	  int getVersion() {
60	    return mi_activity_recognizer_get_version();
61	  }
62	
63	  ~MIActivityRecognizerPy() {
64	    mi_activity_recognizer_free(recognizer_);
65	  }
66	
67	 private:
68	  void *recognizer_;
69	};
70	
71	PYBIND11_MODULE(mi_har_py, m) {
72	  // optional module docstring
73	  m.doc() = "Activity Recognizer model python interface";
74	
75	  // bindings to Worker class
76	  pybind11::class_<MIActivityRecognizerPy>(m, "MIActivityRecognizerPy")
77	      .def(pybind11::init<const float, const int>())
78	      .def("init_algo", &MIActivityRecognizerPy::initAlgo)
79	      .def("process_data", &MIActivityRecognizerPy::handleData)
80	      .def("process_baro", &MIActivityRecognizerPy::handleBaro)
81	      .def("get_in_water", &MIActivityRecognizerPy::getInWater)
82	      .def("get_stair_climbing", &MIActivityRecognizerPy::getStairClimbing)
83	      .def("get_probs", &MIActivityRecognizerPy::getPrediction)
84	      .def("get_type", &MIActivityRecognizerPy::getActivity)
85	      .def("get_version", &MIActivityRecognizerPy::getVersion);
86	}
