20	void *mi_activity_recognizer_new() {
21	  LOGI(LOG_TAG, "Init:%s", mi_algo_har_get_version_info());
22	
23	  MIActivityRecognizer *recognizer =
24	      (MIActivityRecognizer *)generic_malloc(sizeof(MIActivityRecognizer));
