44	void mi_activity_recognizer_init(void          *instance,
45	                                 const float    thd,
46	                                 const uint32_t vote_len) {
47	  if (instance == NULL) {
48	    return;
49	  }
50	  LOGI(LOG_TAG, "cfg,%.2f,%d", thd, vote_len);
51	  MIActivityRecognizer *recognizer = (MIActivityRecognizer *)instance;
52	  recognizer->current_type = MI_HAR_UNKNOWN;
53	  mi_har_model_init(&recognizer->mdl);
54	  mi_har_detector_init(&recognizer->det, thd, vote_len);
55	#ifdef ENABLE_MIHAR_RAWDATA_LOG
56	  LOGE(LOG_TAG, "Algo start");
57	#endif
58	}
