60	/**
61	 * @brief  Process accelerometer data to recognize current activity.
62	 * @note   Accelerometer sample rate should be 26Hz
63	 * @param  *recognizer: Activity Recognizer instance
64	 * @param  acc_x: Accel x axis data, unit: m/s^2
65	 * @param  acc_y: Accel y axis data, unit: m/s^2
66	 * @param  acc_z: Accel z axis data, unit: m/s^2
67	 * @retval 1 when Activity Recognizer updated, 0 otherwise
68	 */
69	int8_t mi_activity_recognizer_process(void *instance,
70	                                      float acc_x,
71	                                      float acc_y,
72	                                      float acc_z) {
73	  if (instance == NULL) {
74	    LOGE(LOG_TAG, "NI");
75	    return 0;
76	  }
77	#ifdef ENABLE_MIHAR_RAWDATA_LOG
78	  LOGE(LOG_TAG,
79	       "Raw,%d,%d,%d",
80	       RAW_FLOAT2INT(acc_x),
81	       RAW_FLOAT2INT(acc_y),
82	       RAW_FLOAT2INT(acc_z));
83	#endif
84	#ifdef ENABLE_TIMECOST_STAT
85	  uint64_t start_us = generic_time_us();
86	#endif
87	  MIActivityRecognizer *recognizer = (MIActivityRecognizer *)instance;
88	  int8_t update = mi_har_model_process(&recognizer->mdl, acc_x, acc_y, acc_z);
89	  if (update) {
90	    MIHARType type = mi_har_model_get_activity_type(&recognizer->mdl);
91	    uint8_t stair_climbing = mi_har_model_get_stair_climbing(&recognizer->mdl);
92	    if (stair_climbing && type == MI_HAR_WALK) {
93	      type = MI_HAR_CLIMB_STAIR;
94	    }
95	
96	    // Swimming requires barometer support: a wrist in the water shows a
97	    // 20~60 hPa peak-to-peak pressure swing per 16s window, which no land
98	    // activity can produce (measured maximum on 198 land recordings:
99	    // 3.68 hPa, see BARO_WATER_* in har_model.h). So a Swim output without
100	    // in-water evidence is a dry-land false positive and is dropped here.
101	    // Fails open on purpose: when no barometer data has been fed in at all,
102	    // mi_har_model_is_water_detect_ready() returns 0 and the accelerometer
103	    // decision is kept as is.
104	    if (type == MI_HAR_SWIM &&
105	        mi_har_model_is_water_detect_ready(&recognizer->mdl) &&
106	        !mi_har_model_get_in_water(&recognizer->mdl)) {
107	      LOGI(LOG_TAG, "SwimDrop: no baro support");
108	      type = MI_HAR_UNKNOWN;
109	    }
110	
111	    // ! HAR Detector processes every 2 seconds
112	    // ! So the number of calls is equal to the detection interval divided by 2
113	    for (int i = 0; i < WIN_SHIFT_S; i += 2) {
114	      LOGV(LOG_TAG, "i: %d,%d", i, WIN_SHIFT_S);
115	      mi_har_detector_process(&recognizer->det, type);
116	    }
117	
118	    uint8_t predict = mi_har_detector_get_activity(&recognizer->det);
119	    if (predict != recognizer->current_type) {
120	      LOGI(LOG_TAG, "Rec,%d>%d", recognizer->current_type, predict);
121	      recognizer->current_type = predict;
122	    }
123	#ifdef ENABLE_TIMECOST_STAT
124	    uint64_t end_us = generic_time_us();
125	    LOGI(LOG_TAG, "TimeCost: %" PRId64 "us", (end_us - start_us));
126	#endif
127	  }
128	
129	  return update;
130	}
