7	
8	#include "common/os_support.h"
9	#include "har_detector_func.h"
10	
11	#define TAG "HARD"
12	
13	#define VOTE_THRESHOLD_MIN (0.30f)
14	#define VOTE_THRESHOLD_HOLD (0.20f)
15	#define VOTE_THRESHOLD_BIKING_MIN (0.55f)
16	#define VOTE_THRESHOLD_ROWING_MIN (0.55f)
17	
18	void mi_har_detector_init(MiHarDetector *det,
19	                          const float    thd,
20	                          uint32_t       vote_len) {
21	  det->init = false;
22	  det->cnt = 0;
23	  det->idx = 0;
24	  if (vote_len < 1) {
25	    vote_len = 1;
26	  } else if (vote_len > HAR_DET_VOTE_LEN_MAX) {
27	    vote_len = HAR_DET_VOTE_LEN_MAX;
28	  }
29	
30	  det->vote_len = vote_len;
31	
32	  for (int32_t i = 0; i < vote_len; ++i) {
33	    det->buffer[i] = MI_HAR_UNKNOWN;
34	  }
35	  det->score_thd = thd;
36	  det->cur_predict = MI_HAR_UNKNOWN;
37	}
38	
39	MiHarDetector *mi_har_detector_new() {
40	  MiHarDetector *det = (MiHarDetector *)generic_malloc(sizeof(MiHarDetector));
41	  return det;
42	}
43	
44	void mi_har_detector_free(MiHarDetector *det) {
45	  if (det != NULL) {
46	    generic_free(det->buffer);
47	    generic_free(det);
48	  }
49	}
50	
51	void vote_majority_score(const uint8_t *in_data,
52	                         const uint32_t vote_len,
53	                         uint8_t       *argmax,
54	                         float         *score) {
55	  uint32_t votes[MI_HAR_NUM_TYPES] = {0};
56	  for (uint8_t i = 0; i < vote_len; ++i) {
57	    uint8_t d = in_data[i];
58	    if (d < MI_HAR_NUM_TYPES) {
59	      votes[d]++;
60	    }
61	  }
62	
63	  uint32_t max_v = votes[0];
64	  *argmax = 0;
65	  for (uint8_t i = 1; i < MI_HAR_NUM_TYPES; ++i) {
66	    if (votes[i] > max_v) {
67	      max_v = votes[i];
68	      *argmax = i;
69	    }
70	  }
71	  *score = ((float)max_v) / vote_len;
72	}
73	
74	int8_t mi_har_detector_process(MiHarDetector *det, MIHARType type) {
75	  det->buffer[det->idx] = type;
76	
77	  det->cnt++;
78	  det->idx++;
79	  if (det->idx >= det->vote_len) {
80	    det->idx = 0;
81	  }
82	
83	  LOGV(TAG, "vote: %d", det->cnt);
84	  int8_t update = 0;
85	  if (det->cnt >= det->vote_len) {
86	    uint8_t argmax;
87	    float   score;
88	    vote_majority_score(det->buffer, det->vote_len, &argmax, &score);
89	    LOGD(TAG, "V,%d,%.4f", argmax, score);
90	    if (score >= det->score_thd) {
91	      det->cur_predict = argmax;
92	      update = 1;
93	    } else if (score < VOTE_THRESHOLD_MIN) {
94	      det->cur_predict = 0;
95	      update = 1;
96	    } else if (det->cur_predict != MI_HAR_UNKNOWN) {
97	      // Dead zone: if current type itself has lost support, release to UNKNOWN
98	      uint32_t cur_votes = 0;
99	      for (uint32_t i = 0; i < det->vote_len; ++i) {
100	        if (det->buffer[i] == det->cur_predict) {
101	          cur_votes++;
102	        }
103	      }
104	      if ((float)cur_votes / det->vote_len < VOTE_THRESHOLD_HOLD) {
105	        det->cur_predict = MI_HAR_UNKNOWN;
106	        update = 1;
107	      }
108	    }
109	
110	    // if (det->cur_predict == MI_HAR_BIKE && score < VOTE_THRESHOLD_BIKING_MIN)
111	    // {
112	    //   det->cur_predict = 0;
113	    //   update = 1;
114	    // } else if (det->cur_predict == MI_HAR_ROWING &&
115	    //            score < VOTE_THRESHOLD_ROWING_MIN) {
116	    //   det->cur_predict = 0;
117	    //   update = 1;
118	    // }
119	  } else {
120	    if (!det->init) {
121	      det->init = true;
122	      det->cur_predict = MI_HAR_UNKNOWN;
123	      update = 1;
124	    }
125	  }
126	
127	  return update;
128	}
129	
130	uint8_t mi_har_detector_get_activity(MiHarDetector *det) {
131	  return det->cur_predict;
132	}
