16	#define TAG "HARM"
17	
18	#define NORM_RAW_DATA 1  // 0: no norm, 1: norm by range
19	#define HAR_PROB_THRESHOLD_MIN (0.45f)
20	#define ALPHA (0.9)
21	
22	MiHarModel *mi_har_model_new() {
23	  MiHarModel *mdl = (MiHarModel *)generic_malloc(sizeof(MiHarModel));
24	  return mdl;
