33	void mi_har_model_init(MiHarModel *mdl) {
34	#ifdef HAR_USE_MACE_MICRO
35	  LOGI(TAG, "Micro%d", WIN_TIME_S);
36	  mdl->handle = har_cnn_GetMaceMicroEngineHandle();
37	#else
38	  LOGI(TAG, "PureC%d", WIN_TIME_S);
39	  mdl->handle = &mdl->handle_c;
40	#endif
41	
42	  mdl->input_shape[0] = 1;
43	  mdl->input_shape[1] = 1;
44	  mdl->input_shape[2] = WIN_LEN;
45	  mdl->input_shape[3] = CHANNEL_NUM;
46	  for (int32_t i = 0; i < BUF_LEN; ++i) {
47	    mdl->in_buffer[i] = 0.0f;
48	  }
49	
50	  for (int32_t i = 0; i < MI_HARM_NUM_TYPES; ++i) {
51	    mdl->probs[i] = 0.0f;
52	  }
53	  mdl->idx = 0;
54	
55	  // Initialize barometer buffer (16s sliding-window cumulative path +
56	  // hysteresis, see har_model.h)
57	  for (int32_t i = 0; i < BARO_WINDOW_LEN; ++i) {
58	    mdl->baro_buffer[i] = 0.0f;
59	  }
60	  mdl->baro_idx = 0;
61	  mdl->baro_write_pos = 0;
62	  mdl->stair_climbing_flag = 0;
63	  mdl->water_win_cnt = 0;
64	  mdl->water_quiet_cnt = 0;
65	  mdl->in_water_flag = 0;
66	
67	  // For smooth
68	#ifdef ENABLE_AVG2
69	  mdl->is_last_init = false;
70	  mdl->last_x = 0.0f;
71	  mdl->last_y = 0.0f;
72	  mdl->last_z = 0.0f;
73	#endif
74	}
75	
76	static inline float calculate_window_std(MiHarModel *mdl) {
77	  float sum = 0.0f;
78	  for (int32_t i = 3; i < BUF_LEN; i += CHANNEL_NUM) {
79	    sum += mdl->in_buffer[i];
80	  }
81	  float avg = sum / WIN_LEN;
82	  sum = 0.0f;
83	  for (int32_t i = 3; i < BUF_LEN; i += CHANNEL_NUM) {
84	    float diff = mdl->in_buffer[i] - avg;
85	    sum += diff * diff;
86	  }
87	
88	  return generic_sqrtf(sum / WIN_LEN);
89	}
90	
91	static inline void scale_data(float *data, float scale, int32_t len) {
92	  for (int32_t i = 0; i < len; ++i) {
93	    data[i] *= scale;
94	  }
95	}
96	
97	int8_t mi_har_model_process(MiHarModel *mdl,
98	                            float       acc_x,
99	                            float       acc_y,
100	                            float       acc_z) {
101	#ifdef ENABLE_AVG2
102	  if (mdl->is_last_init) {
103	    acc_x = acc_x * ALPHA + (1 - ALPHA) * mdl->last_x;
104	    acc_y = acc_y * ALPHA + (1 - ALPHA) * mdl->last_y;
105	    acc_z = acc_z * ALPHA + (1 - ALPHA) * mdl->last_z;
106	  }
107	
108	  mdl->last_x = acc_x;
109	  mdl->last_y = acc_y;
110	  mdl->last_z = acc_z;
111	  mdl->is_last_init = true;
112	#endif
113	
114	  uint32_t s_idx = mdl->idx * 4;
115	  mdl->in_buffer[s_idx] = acc_x;
116	  mdl->in_buffer[s_idx + 1] = acc_y;
117	  mdl->in_buffer[s_idx + 2] = acc_z;
118	  mdl->in_buffer[s_idx + 3] =
119	      generic_sqrtf(acc_x * acc_x + acc_y * acc_y + acc_z * acc_z);
120	
121	  ++mdl->idx;
122	  int8_t updated = 0;
123	  float  type_prob = 0.0f;
124	  if (mdl->idx >= WIN_LEN) {
125	    float   mag_std = calculate_window_std(mdl);
126	    uint8_t argmax = 0;
127	    if (mag_std < HAR_MOVING_MAG_STD_MIN) {
128	      LOGI(TAG, "Lstd:%.6f", mag_std);
129	      mdl->probs[0] = 1.0f;
130	      type_prob = 1.0f;
131	      for (int32_t i = 1; i < MI_HARM_NUM_TYPES; i++) {
132	        mdl->probs[i] = 0.0f;
133	      }
134	    } else {
135	#ifdef HAR_USE_MACE_MICRO
136	      har_cnn_RegisterInputData(
137	          mdl->handle, 0, (void *)mdl->in_buffer, mdl->input_shape);
138	
139	      har_cnn_Interpret(mdl->handle);
140	
141	      har_cnn_GetInterpretResult(mdl->handle,
142	                                 0,
143	                                 &(mdl->out_buffer),
144	                                 &(mdl->out_dims),
145	                                 &(mdl->out_dims_size));
146	      float *output = (float *)mdl->out_buffer;
147	#else
148	#if (NORM_RAW_DATA == 1)
149	      scale_data(mdl->in_buffer, 1.0f / 80.0f, BUF_LEN);
150	#endif
151	
152	#ifdef HAR_USE_VELAAI
153	      float *input = (float *)MiHARGetInput(0);
154	      for (int32_t i = 0; i < BUF_LEN; ++i) {
155	        input[i] = mdl->in_buffer[i];
156	      }
157	      MiHARInvoke();
158	      float *tmp = (float *)MiHARGetOutput(0);
159	      generic_memcpy(mdl->probs, tmp, MI_HARM_NUM_TYPES * sizeof(float));
160	#else
161	      har_model_infer_process_f32s16(mdl->handle, mdl->in_buffer, mdl->probs);
162	#endif
163	
164	#if (NORM_RAW_DATA == 1)
165	      scale_data(mdl->in_buffer, 80.0f, BUF_LEN);
166	#endif
167	
168	      softmax_inplace(mdl->probs, MI_HARM_NUM_TYPES);
169	      float *output = mdl->probs;
170	#endif
171	      for (int32_t i = 0; i < MI_HARM_NUM_TYPES; i++) {
172	        mdl->probs[i] = output[i];
173	        LOGD(TAG, "Probs[%d] = %.6f", i, output[i]);
174	        if (output[i] > output[argmax]) {
175	          argmax = i;
176	        }
177	      }
178	      // Add a threshold in addition to walking
179	      if (argmax > 1 && output[argmax] < HAR_PROB_THRESHOLD_MIN) {
180	        LOGI(TAG, "LP,%d,%.3f", argmax, output[argmax]);
181	        argmax = 0;
182	      }
183	      type_prob = output[argmax];
184	    }
185	
186	    mdl->predict = (MIHARType)argmax;
187	    // Filter low-intensity walking
188	    if (mdl->predict == MI_HAR_WALK) {
189	      if (mag_std < HAR_WALKING_MAG_STD_MIN) {
190	        LOGI(TAG, "sW,%d", (int)(mag_std * 1000));
191	        mdl->predict = MI_HAR_UNKNOWN;
192	      }
193	    }
194	
195	    LOGI(TAG, "PY,%d,%d,%.3f", argmax, mdl->predict, type_prob);
196	
197	    for (int32_t i = WIN_SHIFT_LEN; i < WIN_LEN; ++i) {
198	      for (int32_t j = 0; j < CHANNEL_NUM; ++j) {
199	        mdl->in_buffer[CHANNEL_NUM * (i - WIN_SHIFT_LEN) + j] =
200	            mdl->in_buffer[CHANNEL_NUM * i + j];
201	      }
202	    }
203	    mdl->idx = WIN_LEN - WIN_SHIFT_LEN;
204	    updated = 1;
205	  }
206	  return updated;
207	}
208	
209	
210	// Compute the "cumulative path" (total distance, not displacement) of a
211	// 1Hz barometer window: smooth with a BARO_SMOOTH_WIN-point moving average
212	// to suppress single-sample noise, then sum the absolute change of each
213	// maximal same-direction run on the smoothed curve, excluding runs whose
214	// change is below BARO_MIN_SEG_CHANGE (treated as residual noise after
215	// smoothing). Unlike a first-last difference, ascending and descending
216	// sub-segments inside the window do not cancel each other out. Mirrors
217	// src/py/baro_stair_climbing_analysis.py compute_window_path() with
218	// min_seg_len=2, min_seg_change=BARO_MIN_SEG_CHANGE.
219	//
220	// `window` must hold BARO_WINDOW_LEN samples in chronological order
221	// (oldest first).
222	static float compute_baro_window_path(const float *window) {
223	  float   smoothed[BARO_WINDOW_LEN - BARO_SMOOTH_WIN + 1];
224	  int32_t smoothed_len = BARO_WINDOW_LEN - BARO_SMOOTH_WIN + 1;
225	  for (int32_t i = 0; i < smoothed_len; ++i) {
226	    float sum = 0.0f;
227	    for (int32_t j = 0; j < BARO_SMOOTH_WIN; ++j) {
228	      sum += window[i + j];
229	    }
230	    smoothed[i] = sum / (float)BARO_SMOOTH_WIN;
231	  }
232	  if (smoothed_len < 2) {
233	    return 0.0f;
234	  }
235	
236	  float   path = 0.0f;
237	  int32_t i = 0;
238	  while (i < smoothed_len - 1) {
239	    float   diff = smoothed[i + 1] - smoothed[i];
240	    float   cur_sign = (diff > 0.0f) ? 1.0f : ((diff < 0.0f) ? -1.0f : 0.0f);
241	    int32_t seg_start = i;
242	    int32_t j = i;
243	    // Extend the run while consecutive diffs keep the same sign (0 diffs
244	    // are absorbed into the current run, matching the Python reference).
245	    while (j < smoothed_len - 1) {
246	      float d = smoothed[j + 1] - smoothed[j];
247	      float s = (d > 0.0f) ? 1.0f : ((d < 0.0f) ? -1.0f : 0.0f);
248	      if (s != cur_sign && s != 0.0f) {
249	        break;
250	      }
251	      ++j;
252	    }
253	    // seg_len (number of smoothed points in this run, i.e. j-seg_start+1)
254	    // is always >= 2 here since we only reach this point after at least
255	    // one direction-preserving step from seg_start to j (min_seg_len=2 in
256	    // the Python reference is therefore always satisfied and not checked
257	    // explicitly). Only accumulate runs whose change exceeds
258	    // BARO_MIN_SEG_CHANGE; smaller runs are residual noise left after
259	    // smoothing and are excluded from the path (mirrors Python's
260	    // min_seg_change filter).
261	    if (cur_sign != 0.0f) {
262	      float seg_change = generic_fabsf(smoothed[j] - smoothed[seg_start]);
263	      if (seg_change >= BARO_MIN_SEG_CHANGE) {
264	        path += seg_change;
265	      }
266	    }
267	    i = j;
268	    if (j == seg_start) {
269	      // cur_sign was 0 at a single point with no further extension
270	      // possible; advance by one to avoid an infinite loop.
271	      ++i;
272	    }
273	  }
274	  return path;
275	}
276	
277	// In-water detection: peak-to-peak of the shared 16s baro ring buffer plus
278	// asymmetric hysteresis (see BARO_WATER_* in har_model.h). Order inside the
279	// ring does not matter for a min/max feature, so the buffer is read raw
280	// instead of being unwrapped chronologically. Mirrors
281	// src/py/baro_stair_climbing_analysis.py InWaterDetector.
282	// Returns the window peak-to-peak in hPa, or 0 while the window is not full.
283	static float update_in_water_state(MiHarModel *mdl) {
284	  if (mdl->water_win_cnt < BARO_WINDOW_LEN) {
285	    mdl->water_win_cnt++;
286	  }
287	  if (mdl->water_win_cnt < BARO_WINDOW_LEN) {
288	    return 0.0f;
289	  }
290	
291	  float min_v = mdl->baro_buffer[0];
292	  float max_v = mdl->baro_buffer[0];
293	  for (int32_t i = 1; i < BARO_WINDOW_LEN; ++i) {
294	    float v = mdl->baro_buffer[i];
295	    if (v < min_v) {
296	      min_v = v;
297	    }
298	    if (v > max_v) {
299	      max_v = v;
300	    }
301	  }
302	  float ptp = max_v - min_v;
303	
304	  uint8_t prev_flag = mdl->in_water_flag;
305	  if (mdl->in_water_flag == 1) {
306	    if (ptp < BARO_WATER_EXIT_PTP) {
307	      if (mdl->water_quiet_cnt < BARO_WATER_EXIT_HOLD_S) {
308	        mdl->water_quiet_cnt++;
309	      }
310	      if (mdl->water_quiet_cnt >= BARO_WATER_EXIT_HOLD_S) {
311	        mdl->in_water_flag = 0;
312	        mdl->water_quiet_cnt = 0;
313	      }
314	    } else {
315	      mdl->water_quiet_cnt = 0;
316	    }
317	  } else {
318	    if (ptp > BARO_WATER_ENTER_PTP) {
319	      mdl->in_water_flag = 1;
320	      mdl->water_quiet_cnt = 0;
321	    }
322	  }
323	
324	  LOGD(TAG, "InWaterPtp: ptp=%.3f, flag=%d", ptp, mdl->in_water_flag);
325	  if (mdl->in_water_flag != prev_flag) {
326	    LOGI(TAG,
327	         "InWaterPtp: %d->%d, ptp=%.3f",
328	         prev_flag,
329	         mdl->in_water_flag,
330	         ptp);
331	  }
332	  return ptp;
333	}
334	
335	void mi_har_model_process_baro(MiHarModel *mdl, uint32_t ts_ms, float baro) {
336	  if (mdl == NULL) {
337	    return;
338	  }
339	
340	  // Reject out-of-range samples outright: the offline swim recordings
341	  // contain sentinel values around -1e8 hPa on dropped samples, and a
342	  // single one of those would blow up both the cumulative path and the
343	  // peak-to-peak feature.
344	  if (!(baro > BARO_VALID_MIN && baro < BARO_VALID_MAX)) {
345	    LOGD(TAG, "BaroDrop: %d", (int32_t)baro);
346	    return;
347	  }
348	
349	  // 16s sliding-window cumulative path + hysteresis (scheme C, see
350	  // BARO_WINDOW_LEN/BARO_SMOOTH_WIN/BARO_ENTER_PATH_THRESHOLD/
351	  // BARO_HOLD_PATH_THRESHOLD in har_model.h). Mirrors
352	  // src/py/baro_cumulative_path_detector.py CumulativePathDetector +
353	  // src/py/baro_path_hysteresis.py PathHysteresisDetector: every new 1Hz
354	  // sample re-evaluates the path over the most recent BARO_WINDOW_LEN
355	  // samples (ring buffer), and the hysteresis state machine updates
356	  // in-place.
357	  mdl->baro_buffer[mdl->baro_write_pos] = baro;
358	  mdl->baro_write_pos++;
359	  if (mdl->baro_write_pos >= BARO_WINDOW_LEN) {
360	    mdl->baro_write_pos = 0;
361	  }
362	  if (mdl->baro_idx < BARO_WINDOW_LEN) {
363	    mdl->baro_idx++;
364	  }
365	
366	  // In-water detection runs first: it shares the same ring buffer. Note that
367	  // the stair-climbing guard below is deliberately NOT tied to the in-water
368	  // state: in_water carries a BARO_WATER_EXIT_HOLD_S hold (needed for
369	  // poolside rests), and hanging stair climbing off it would disable stair
370	  // detection for that whole hold after any large pressure excursion - an
371	  // elevator ride being the common one (measured: a 1.4 m/s elevator inside
372	  // a stair-climbing recording peaks at 3.78 hPa per 16s window, and faster
373	  // office elevators will cross BARO_WATER_ENTER_PTP). Riding an elevator
374	  // and then walking to the stairs is a frequent pattern, so the stair guard
375	  // instead keys off the *instantaneous* window validity: a window holding
376	  // an excursion no human stair climb can produce is simply not evaluated,
377	  // and the ring has to refill with clean samples first. That still prevents
378	  // the post-swim fake climb (water samples give 20~60 hPa), but recovers
379	  // within BARO_WINDOW_LEN seconds instead of the full hold.
380	  float ptp = update_in_water_state(mdl);
381	  if (ptp > BARO_STAIR_MAX_PTP) {
382	    mdl->baro_idx = 0;
383	    if (mdl->stair_climbing_flag != 0) {
384	      LOGI(TAG,
385	           "StairClimbingPath: %d->0, ptp=%.3f too large",
386	           mdl->stair_climbing_flag,
387	           ptp);
388	      mdl->stair_climbing_flag = 0;
389	    }
390	    return;
391	  }
392	
393	  if (mdl->baro_idx >= BARO_WINDOW_LEN) {
394	    // Unwrap the ring buffer into chronological order for path computation.
395	    float window[BARO_WINDOW_LEN];
396	    for (int32_t i = 0; i < BARO_WINDOW_LEN; ++i) {
397	      window[i] = mdl->baro_buffer[(mdl->baro_write_pos + i) % BARO_WINDOW_LEN];
398	    }
399	    float path = compute_baro_window_path(window);
400	
401	    uint8_t prev_flag = mdl->stair_climbing_flag;
402	    if (mdl->stair_climbing_flag == 1) {
403	      if (path < BARO_HOLD_PATH_THRESHOLD) {
404	        mdl->stair_climbing_flag = 0;
405	      }
406	    } else {
407	      if (path > BARO_ENTER_PATH_THRESHOLD) {
408	        mdl->stair_climbing_flag = 1;
409	      }
410	    }
411	    // Every-window path value at LOGD (verbose), state transition at LOGI
412	    // (default-visible) so a switch between climbing/non-climbing can be
413	    // spotted directly in the default log level without scrolling through
414	    // a per-window dump.
415	    LOGD(TAG,
416	         "StairClimbingPath: path=%.3f, flag=%d",
417	         path,
418	         mdl->stair_climbing_flag);
419	    if (mdl->stair_climbing_flag != prev_flag) {
420	      LOGI(TAG,
421	           "StairClimbingPath: %d->%d, path=%.3f",
422	           prev_flag,
423	           mdl->stair_climbing_flag,
424	           path);
425	    }
426	  }
427	}
