447	uint8_t mi_har_model_is_water_detect_ready(MiHarModel *mdl) {
448	  if (mdl == NULL) {
449	    return 0;
450	  }
451	  // Only meaningful once a full window of barometer samples has been fed
452	  // in. Callers use this to fail open when no barometer data is available
453	  // at all, so that swimming is never suppressed for missing evidence.
454	  return (uint8_t)(mdl->water_win_cnt >= BARO_WINDOW_LEN);
