18	static inline int cal_conv_out_size(int in_size, int kernel_size, int stride,
19	                                    int padding, int dilation) {
20	  return ((((in_size + 2 * padding) - ((kernel_size - 1) * dilation) - 1) /
21	           stride) +
22	          1);
23	}
24	
25	static inline int cal_conv_out_size_ex(int in_size, const Conv1DParam *param) {
26	  return cal_conv_out_size(in_size, param->kernel_size, param->stride,
27	                           param->padding, param->dilation);
28	}
