42	static inline void fill_feat_buf(const float *out_buf, int len, int ch,
43	                                 int ch_shift, float *feat_buf) {
44	  // Fill to final feat buffer
45	  // 每个CB输出52*8,4个CB需要拼接起来, 得到52*32
46	  for (int i = 0; i < len; ++i) {
47	    for (int j = 0; j < ch; ++j) {
48	      int idx1 = i * MS_FEAT_CH + j + ch_shift;
49	      int idx2 = i * ch + j;
50	      feat_buf[idx1] = out_buf[idx2];
51	    }
52	  }
53	}
54	
55	static int16_t conv_block_infer(const Conv1DF32 *conv, const float *in_buf,
56	                                int node_num, float *out_buf, const float *bnw,
57	                                const float *bnb, bool pooling) {
58	  conv1d_inf_f32(conv, in_buf, node_num, out_buf);
59	  int out_len = cal_conv_out_size_ex(node_num, conv->param);
60	  print_arr_head("ConvOut", out_buf);
61	
62	  batch_norm_inplace(bnw, bnb, out_buf, out_len, conv->param->out_ch);
63	
64	  activation_relu_inplace(out_buf, out_len * conv->param->out_ch);
65	
66	  // TODO(Farmer): Hard code the stride to 2
67	  if (pooling) {
68	    max_pooling(out_buf, out_buf, out_len, conv->param->out_ch, 2);
69	    out_len /= 2;
70	  }
71	
72	  return out_len;
73	}
74	
75	void har_model_infer_process(void *instance, const float *in_buf,
76	                             float *out_buf) {
77	  HarModelInfer *inst = (HarModelInfer *)instance;
78	
79	  int    in_len = IN_LEN;
80	  float *buf1 = inst->buf1;
81	  float *buf2 = inst->buf2;
82	  int    ch_shift = 0;
83	
84	  // 每个CB输入104*4,经过Conv1D,ReLU,MaxPooling(可选),输出52*8
85	  // CB1
86	  conv_block_infer(&kCB1ConvS, in_buf, in_len, buf1, kCB1BnW, kCB1BnB, true);
87	  fill_feat_buf(buf1, MS_CB_OL, MS_CNN_OC, ch_shift, buf2);
88	  ch_shift += MS_CNN_OC;
89	
90	  // CB2
91	  conv_block_infer(&kCB2ConvS, in_buf, in_len, buf1, kCB2BnW, kCB2BnB, true);
92	  fill_feat_buf(buf1, MS_CB_OL, MS_CNN_OC, ch_shift, buf2);
93	  ch_shift += MS_CNN_OC;
94	
95	  // CB3
96	  conv_block_infer(&kCB3ConvS, in_buf, in_len, buf1, kCB3BnW, kCB3BnB, true);
97	  fill_feat_buf(buf1, MS_CB_OL, MS_CNN_OC, ch_shift, buf2);
98	  ch_shift += MS_CNN_OC;
99	
100	  // CB4
101	  conv_block_infer(&kCB4ConvS, in_buf, in_len, buf1, kCB4BnW, kCB4BnB, true);
102	  fill_feat_buf(buf1, MS_CB_OL, MS_CNN_OC, ch_shift, buf2);
103	  ch_shift += MS_CNN_OC;
104	
105	  // Fusion CB
106	  // 输入: 52*32
107	  // 输出: 52*32
108	  // 无MaxPooling
109	  conv_block_infer(&kFusionConvS, buf2, MS_CB_OL, buf1, kFusionBnW, kFusionBnB,
110	                   false);
111	
112	  // Enhance CB
113	  // 输入: 52*32
114	  // 输出: 52*16
115	  // 无MaxPooling
116	  conv_block_infer(&kEnConvS, buf1, MS_CB_OL, buf2, kEnBnW, kEnBnB, false);
117	
118	  // SEBlock
119	  // Global Average Pooling，输入52*16, 输出1*16
120	  float se_buf1[EN_CNN_OUT_CH] = {0.0f};
121	  float se_bu2f[EN_CNN_OUT_CH] = {0.0f};
122	  global_average_pooling(buf2, se_buf1, MS_CB_OL, kEnConvS.param->out_ch);
123	  // FC1, 输入1*16, 输出1*4
124	  dense_forward(kSEFc0W, kSEFc0B, se_buf1, se_bu2f, kSEFc0Ich, kSEFc0Och);
125	  activation_relu_inplace(se_bu2f, kSEFc0Och);
126	
127	  // FC2, 输入1*4, 输出1*16
128	  dense_forward(kSEFc2W, kSEFc2B, se_bu2f, se_buf1, kSEFc2Ich, kSEFc2Och);
129	  activation_sigmoid_inplace(se_buf1, kSEFc2Och);
130	
131	  // 应用权重到每个特征通道
132	  for (int i = 0; i < MS_CB_OL; ++i) {
133	    for (int j = 0; j < EN_CNN_OUT_CH; ++j) {
134	      buf2[i * EN_CNN_OUT_CH + j] *= se_buf1[j];
135	    }
136	  }
137	
138	  // Global Average Pooling，输入52*16, 输出1*16
139	  global_average_pooling(buf2, se_buf1, MS_CB_OL, kEnConvS.param->out_ch);
140	
141	  // FC1
142	  dense_forward(kFC1W, kFC1B, se_buf1, buf2, kFC1Ich, kFC1Och);
143	  activation_relu_inplace(buf2, kFC1Och);
144	
145	  // FC2, 输入1*16, 输出1*8
146	  dense_forward(kFC2W, kFC2B, buf2, buf1, kFC2Ich, kFC2Och);
147	
148	  if (out_buf != NULL) {
149	    for (int i = 0; i < MI_HAR_NUM_TYPES; ++i) {
150	      out_buf[i] = buf1[i];
151	    }
152	  }
153	}
